// Ticket goodwill compensation: credit spendable bonus days, write the
// auditable grant row and append the user-visible support message in ONE
// serializable transaction. `requestId` (generated by the admin panel) makes a
// retried confirm idempotent — the unique constraint is the final guard.
  import { isUniqueViolation, isWriteConflict } from './prisma-errors';
  import { prisma } from './prisma';
  import { t } from './i18n';
import {
  COMPENSATION_MAX_DAYS,
  COMPENSATION_MAX_PER_TICKET,
  compensationReasonLabel,
  type CompensationReason,
} from './ticket-compensation-reasons';

export interface CompensationSummary {
  used: number;
  maxDays: number;
}

export type CompensateOutcome =
  | {
      ok: true;
      days: number;
      bonusDays: number;
      messageId: string;
      /** false when the same requestId already granted (idempotent retry). */
      created: boolean;
      email: string | null;
      subject: string;
      body: string;
    }
  | { ok: false; reason: 'not_found' | 'invalid' | 'limit' | 'conflict' };

  /** Aggregate for the admin panel: how much of this ticket's cap is spent. */
export async function loadTicketCompensationSummary(
  ticketId: string,
): Promise<CompensationSummary> {
  const sum = await prisma.ticketCompensation.aggregate({
    where: { ticketId },
    _sum: { days: true },
  });
  return {
    used: Math.max(0, sum._sum.days ?? 0),
    maxDays: COMPENSATION_MAX_PER_TICKET,
  };
}

export async function compensateTicketWithBonusDays(input: {
  ticketId: string;
  adminTelegramId: bigint;
  days: number;
  reason: CompensationReason;
  comment: string | null;
  requestId: string;
}): Promise<CompensateOutcome> {
  if (
    !Number.isSafeInteger(input.days) ||
    input.days < 1 ||
    input.days > COMPENSATION_MAX_DAYS
  ) {
    return { ok: false, reason: 'invalid' };
  }

  try {
    const result = await prisma.$transaction(
      async (tx): Promise<CompensateOutcome> => {
        const existing = await tx.ticketCompensation.findUnique({
          where: { requestId: input.requestId },
          select: { ticketId: true, days: true, messageId: true },
        });
        if (existing) {
          if (existing.ticketId !== input.ticketId) {
            return { ok: false, reason: 'conflict' };
          }
          const current = await tx.ticket.findUnique({
            where: { id: existing.ticketId },
            select: { user: { select: { bonusDays: true } } },
          });
          return {
            ok: true,
            days: existing.days,
            bonusDays: Math.max(0, current?.user.bonusDays ?? 0),
            messageId: existing.messageId,
            created: false,
            email: null,
            subject: '',
            body: '',
          };
        }

        const ticket = await tx.ticket.findUnique({
          where: { id: input.ticketId },
          select: {
            subject: true,
            user: { select: { id: true, email: true } },
          },
        });
        if (!ticket) return { ok: false, reason: 'not_found' };

        const used = await tx.ticketCompensation.aggregate({
          where: { ticketId: input.ticketId },
          _sum: { days: true },
        });
        if ((used._sum.days ?? 0) + input.days > COMPENSATION_MAX_PER_TICKET) {
          return { ok: false, reason: 'limit' };
        }

        const body = t('ticket.compensationMessage', {
          days: input.days,
          reason: compensationReasonLabel(input.reason),
        });
        const message = await tx.ticketMessage.create({
          data: { ticketId: input.ticketId, author: 'support', body },
          select: { id: true },
        });
        await tx.ticketCompensation.create({
          data: {
            ticketId: input.ticketId,
            adminTelegramId: input.adminTelegramId,
            days: input.days,
            reason: input.reason,
            comment: input.comment,
            requestId: input.requestId,
            messageId: message.id,
          },
        });
        const user = await tx.user.update({
          where: { id: ticket.user.id },
          data: { bonusDays: { increment: input.days } },
          select: { bonusDays: true },
        });
        await tx.ticket.updateMany({
          where: { id: input.ticketId },
          data: {
            status: 'answered',
            unreadForUser: { increment: 1 },
            unreadForAdmin: 0,
            lastMessageAt: new Date(),
          },
        });

        return {
          ok: true,
          days: input.days,
          bonusDays: Math.max(0, user.bonusDays),
          messageId: message.id,
          created: true,
          email: ticket.user.email || null,
          subject: ticket.subject,
          body,
        };
      },
      { isolationLevel: 'Serializable' },
    );

    // Mirror the support message to email after the grant is committed. A mail
    // failure never rolls back the compensation; Telegram is enqueued by the
    // route and the cabinet thread always has the message.
    if (result.ok && result.created && result.email) {
      try {
        const { sendTicketReplyMail } = await import('./mail');
        void sendTicketReplyMail(
          result.email,
          input.ticketId,
          result.subject,
          result.body,
        ).catch(() => undefined);
      } catch {
        // Best-effort mirror only.
      }
    }

    return result;
  } catch (err) {
    if (isWriteConflict(err) || isUniqueViolation(err)) {
      return { ok: false, reason: 'conflict' };
    }
    throw err;
  }
}
